def run(params, grid, demos):
    background = int(round(params['colors'][0]))
    intersection = int(round(params['colors'][1]))
    points = np.argwhere(grid != background)
    result = grid.copy()
    for r, c in points:
        color = int(grid[r, c])
        result[r, :] = color
        result[:, c] = color
    for r, c in points:
        for s, t in points:
            if r != s and c != t:
                result[r, t] = intersection
    return result

def search(remaining, tiles, lookup):
    if not remaining:
        return []
    choices = None
    for cell in remaining:
        available = []
        for index in lookup[cell]:
            cells, color = tiles[index]
            if cells.issubset(remaining):
                available.append(index)
        if not available:
            return None
        if choices is None or len(available) < len(choices):
            choices = available
    for index in choices:
        cells, color = tiles[index]
        result = search(remaining.difference(cells), tiles, lookup)
        if result is not None:
            return [index] + result
    return None
