    offsets = params['offsets']
    if any(count <= 0 or count > len(offsets[index]) for index, count in enumerate(counts)):
        return grid.copy()
    height, width = grid.shape
    remaining = set((int(row), int(col)) for row, col in np.argwhere(grid == foreground))
    lookup = {cell: [] for cell in remaining}
    tiles = []
    for row, col in remaining:
        for kind, count in enumerate(counts):
            cells = set()
            for index in range(count):
                dr = int(round(offsets[kind][index][0]))
                dc = int(round(offsets[kind][index][1]))
                cells.add((row + dr, col + dc))
            if len(cells) == count and cells.issubset(remaining):
                tile_index = len(tiles)
                tiles.append((cells, colors[kind]))
                for cell in cells:
                    lookup[cell].append(tile_index)
    solution = search(remaining, tiles, lookup)
    output = grid.copy()
    if solution is not None:
        for index in solution:
            cells, color = tiles[index]
            for row, col in cells:
                output[row, col] = color
    return output

