    if not remaining:
        return []
    best = None
    options = None
    for cell in remaining:
        valid = []
        for index in choices.get(cell, []):
            if pieces[index][0].issubset(remaining):
                valid.append(index)
        if not valid:
            return None
        if options is None or len(valid) < len(options):
            best = cell
            options = valid
    for index in options:
        result = cover(remaining.difference(pieces[index][0]), choices, pieces)
        if result is not None:
            return [index] + result
    return None
