def run(params, grid, demos):
    blank = int(round(params['colors'][0]))
    exterior = int(round(params['colors'][1]))
    interior = int(round(params['colors'][2]))
    low = int(round(params['bounds'][0]))
    step = int(round(params['bounds'][1]))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    height, width = grid.shape
    out = grid.copy()
    out[grid == blank] = interior
    pending = []
    visited = set()
    for r in range(height):
        for c in range(width):
            if grid[r, c] == blank:
                if r == low or c == low or r == height - step or c == width - step:
                    visited.add((r, c))
                    pending.append((r, c))
    while pending:
        r, c = pending.pop()
        out[r, c] = exterior
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if low <= nr < height and low <= nc < width:
                if (nr, nc) not in visited and grid[nr, nc] == blank:
                    visited.add((nr, nc))
                    pending.append((nr, nc))
    return out

def run(params, grid, demos):
    background = int(round(params['colors'][0]))
    exterior = int(round(params['colors'][1]))
    interior = int(round(params['colors'][2]))
    low = int(round(params['bounds'][0]))
    unit = int(round(params['bounds'][1]))
    directions = [(int(round(pair[0])), int(round(pair[1]))) for pair in params['directions']]
    h, w = grid.shape
    out = grid.copy()
    seen = np.zeros((h, w), dtype=bool)
    pending = []
    for r in range(h):
        for c in range(w):
            if grid[r, c] == background:
                out[r, c] = interior
                if r == low or c == low or r == h - unit or c == w - unit:
                    seen[r, c] = True
                    pending.append((r, c))
    while pending:
        r, c = pending.pop()
        out[r, c] = exterior
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if low <= nr < h and low <= nc < w:
                if not seen[nr, nc] and grid[nr, nc] == background:
                    seen[nr, nc] = True
                    pending.append((nr, nc))
    return out

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    source = int(round(params['rule'][1]))
    fill = int(round(params['rule'][2]))
    size = int(round(params['rule'][3]))
    out = grid.copy()
    if size <= 0:
        return out
    points = np.argwhere(grid == source)
    if len(points) == 0:
        return out
    top = int(np.min(points[:, 0]))
    left = int(np.min(points[:, 1]))
    height, width = grid.shape
    for row in range(top, height, size):
        for col in range(left, width, size):
            block = grid[row:row + size, col:col + size]
            if np.any(block == source):
                out[row:row + size, col:col + size] = np.where(block == background, fill, block)
    return out

def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    fg = int(round(params['colors'][1]))
    fill = int(round(params['colors'][2]))
    near = int(round(params['merge'][0]))
    overlap = int(round(params['merge'][1]))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    h, w = grid.shape
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r, c] != fg or (r, c) in seen:
                continue
            pending = [(r, c)]
            seen.add((r, c))
            rows = []
            cols = []
            while pending:
                y, x = pending.pop()
                rows.append(y)
                cols.append(x)
                for dy, dx in directions:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if grid[yy, xx] == fg and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            pending.append((yy, xx))
            boxes.append([min(rows), max(rows), min(cols), max(cols)])
    changed = True
    while changed:
        changed = False
        for i in range(len(boxes)):
            if changed:
                break
            for j in range(i + 1, len(boxes)):
                a, b = boxes[i], boxes[j]
                rowgap = max(a[0] - b[1], b[0] - a[1])
                colgap = max(a[2] - b[3], b[2] - a[3])
                if (rowgap <= overlap and colgap <= near) or (colgap <= overlap and rowgap <= near):
                    boxes[i] = [min(a[0], b[0]), max(a[1], b[1]), min(a[2], b[2]), max(a[3], b[3])]
                    boxes.pop(j)
                    changed = True
                    break
    out = grid.copy()
    for top, bottom, left, right in boxes:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                if out[r, c] == bg:
                    out[r, c] = fill
    return out

def run(params, grid, demos):
    blank = int(round(params['colors'][0]))
    separator = int(round(params['colors'][1]))
    removed = int(round(params['colors'][2]))
    added = int(round(params['colors'][3]))
    axis = int(round(params['layout'][0]))
    gap = int(round(params['layout'][1]))
    if axis not in (0, 1) or gap < 1:
        return grid.copy()
    work = grid.T if axis == 1 else grid
    cuts = np.argwhere(np.all(work == separator, axis=1)).flatten()
    if len(cuts) != 1:
        return grid.copy()
    cut = int(cuts[0])
    first = work[:cut]
    second = work[cut + gap:]
    if first.shape != second.shape:
        return grid.copy()
    changed = first != second
    result = first.copy()
    result[np.logical_and(changed, first != blank)] = removed
    result[np.logical_and(changed, second != blank)] = added
    return result.T if axis == 1 else result

def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    wall = int(round(params['colors'][1]))
    marker = int(round(params['colors'][2]))
    paint = int(round(params['colors'][3]))
    directions = [(int(round(v[0])), int(round(v[1]))) for v in params['directions']]
    horizontal = int(round(params['settings'][0]))
    boundary = int(round(params['settings'][1]))
    out = grid.copy()
    h, w = grid.shape
    seeds = []
    marks = np.argwhere(grid == marker)
    for pos in marks:
        r, c = int(pos[0]), int(pos[1])
        adjacent = []
        for dr, dc in directions[:horizontal]:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w and grid[rr, cc] == bg:
                adjacent.append((rr, cc))
        seeds.extend(adjacent)
        if len(adjacent) == horizontal:
            out[r, c] = paint
    if len(marks) == 0:
        for r in range(h):
            if grid[r, boundary] != bg:
                continue
            enclosed = True
            for dr, dc in directions[horizontal:]:
                rr, cc = r + dr, boundary + dc
                if not (0 <= rr < h and 0 <= cc < w and grid[rr, cc] == wall):
                    enclosed = False
            if enclosed:
                seeds.append((r, boundary))
    seen = set(seeds)
    queue = list(seeds)
    index = 0
    while index < len(queue):
        r, c = queue[index]
        index += 1
        out[r, c] = paint
        for dr, dc in directions:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w and (rr, cc) not in seen and grid[rr, cc] == bg:
                seen.add((rr, cc))
                queue.append((rr, cc))
    return out

def run(params, grid, demos):
    bg = int(round(params['background'][0]))
    step = int(round(params['geometry'][0]))
    minimum = int(round(params['geometry'][1]))
    out = grid.copy()
    if step <= 0 or minimum <= step + step:
        return out
    height, width = grid.shape
    for value in params['palette']:
        color = int(round(value))
        if color == bg:
            continue
        points = np.argwhere(grid == color)
        if len(points) == 0:
            continue
        top = int(np.min(points[:, 0]))
        bottom = int(np.max(points[:, 0])) + step
        left = int(np.min(points[:, 1]))
        right = int(np.max(points[:, 1])) + step
        frame_height = bottom - top
        frame_width = right - left
        if frame_height < minimum or frame_width < minimum:
            continue
        if not np.all(grid[top:top + step, left:right] == color):
            continue
        if not np.all(grid[bottom - step:bottom, left:right] == color):
            continue
        if not np.all(grid[top:bottom, left:left + step] == color):
            continue
        if not np.all(grid[top:bottom, right - step:right] == color):
            continue
        if not np.all(grid[top + step:bottom - step, left + step:right - step] == bg):
            continue
        for row in range(height - frame_height + step):
            for col in range(width - frame_width + step):
                end_row = row + frame_height
                end_col = col + frame_width
                if np.all(grid[row + step:end_row - step, col + step:end_col - step] == bg):
                    out[row:row + step, col:end_col] = color
                    out[end_row - step:end_row, col:end_col] = color
                    out[row:end_row, col:col + step] = color
                    out[row:end_row, end_col - step:end_col] = color
    return out

def run(params, grid, demos):
    bg = int(round(params['background'][0]))
    step = int(round(params['geometry'][0]))
    minimum = int(round(params['geometry'][1]))
    out = grid.copy()
