        return out
    height, width = grid.shape
    for value in params['palette']:
        color = int(round(value))
        if color == bg:
            continue
        points = np.argwhere(grid == color)
        if len(points) == 0:
            continue
        top = int(points[:, 0].min())
        bottom = int(points[:, 0].max()) + step
        left = int(points[:, 1].min())
        right = int(points[:, 1].max()) + step
        rh = bottom - top
        rw = right - left
        if rh < minimum or rw < minimum:
            continue
        if not np.all(grid[top:top + step, left:right] == color):
            continue
        if not np.all(grid[bottom - step:bottom, left:right] == color):
            continue
        if not np.all(grid[top:bottom, left:left + step] == color):
            continue
        if not np.all(grid[top:bottom, right - step:right] == color):
            continue
        if not np.all(grid[top + step:bottom - step, left + step:right - step] == bg):
            continue
        for row in range(height - rh + step):
            for col in range(width - rw + step):
                interior = grid[row + step:row + rh - step, col + step:col + rw - step]
                if np.all(interior == bg):
                    out[row:row + step, col:col + rw] = color
                    out[row + rh - step:row + rh, col:col + rw] = color
                    out[row:row + rh, col:col + step] = color
                    out[row:row + rh, col + rw - step:col + rw] = color
        return out
    return out

def run(params, grid, demos):
    bg = int(round(params['background'][0]))
    moves = []
    for row in params['moves']:
        moves.append([int(round(v)) for v in row])
    out = grid.copy()
    h, w = grid.shape
    for r in range(h):
        for c in range(w):
            if grid[r, c] != bg:
                continue
            valid = True
            for dr, dc, sr, sc in moves:
                if not (0 <= r + dr < h and 0 <= c + dc < w and 0 <= r + sr < h and 0 <= c + sc < w):
                    valid = False
                    break
                if grid[r + sr, c + sc] == bg:
                    valid = False
                    break
            if valid:
                for dr, dc, sr, sc in moves:
                    out[r + dr, c + dc] = grid[r + sr, c + sc]
    return out

def run(params, grid, demos):
    background = int(round(params['colours'][0]))
    wall = int(round(params['colours'][1]))
    marker = int(round(params['colours'][2]))
    fill = int(round(params['colours'][3]))
    threshold = int(round(params['threshold'][0]))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    pairs = []
    for pair in params['pairs']:
        pairs.append((int(round(pair[0])), int(round(pair[1]))))
    height, width = grid.shape
    eligible = np.zeros(grid.shape, dtype=bool)
    starts = []
    for r in range(height):
        for c in range(width):
            neighbours = []
            for dr, dc in directions:
                rr, cc = r + dr, c + dc
                neighbours.append(0 <= rr < height and 0 <= cc < width and grid[rr, cc] == wall)
            straight = False
            for a, b in pairs:
                if 0 <= a < len(neighbours) and 0 <= b < len(neighbours):
                    if neighbours[a] and neighbours[b]:
                        straight = True
            value = grid[r, c]
            if value == background and sum(neighbours) >= threshold:
                eligible[r, c] = True
            elif value == marker and straight:
                eligible[r, c] = True
            if eligible[r, c] and straight:
                boundary = False
                for dr, dc in directions:
                    rr, cc = r + dr, c + dc
                    if rr < 0 or rr >= height or cc < 0 or cc >= width:
                        boundary = True
                if boundary:
                    starts.append((r, c))
    result = grid.copy()
    if not starts or fill < 0 or fill > 9:
        return result
    pending = [starts[0]]
    visited = set()
    while pending:
        r, c = pending.pop()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        result[r, c] = fill
        for dr, dc in directions:
            rr, cc = r + dr, c + dc
            if 0 <= rr < height and 0 <= cc < width:
                if eligible[rr, cc] and (rr, cc) not in visited:
                    pending.append((rr, cc))
    return result

def run(params, grid, demos):
    background = int(round(params['background'][0]))
    offsets = [(int(round(row[0])), int(round(row[1]))) for row in params['offsets']]
    permutation = [int(round(value)) for value in params['permutation']]
    result = grid.copy()
    height, width = grid.shape
    if any(index < 0 or index >= len(offsets) for index in permutation):
        return result
    for row in range(height):
        for col in range(width):
            if grid[row, col] != background:
                continue
            positions = [(row + dr, col + dc) for dr, dc in offsets]
            if any(r < 0 or r >= height or c < 0 or c >= width for r, c in positions):
                continue
            if any(grid[r, c] == background for r, c in positions):
                continue
            values = [grid[r, c] for r, c in positions]
            for index, position in enumerate(positions):
                r, c = position
                result[r, c] = values[permutation[index]]
    return result

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    seed = int(round(params['rule'][1]))
    diagonal = int(round(params['rule'][2]))
    ray = int(round(params['rule'][3]))
    marker = int(round(params['rule'][4]))
    radius = int(round(params['rule'][5]))
    period = int(round(params['rule'][6]))
    out = grid.copy()
    points = np.argwhere(grid == seed)
    if len(points) == 0 or period <= 0:
        return out
    center = np.mean(points, axis=0)
    cr = int(round(center[0]))
    cc = int(round(center[1]))
    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if grid[r, c] != bg:
                continue
            dr = abs(r - cr)
            dc = abs(c - cc)
            if dr == dc and dr >= radius:
                out[r, c] = diagonal
            elif r == cr or c == cc:
                distance = max(dr, dc)
                if distance > radius:
                    if (distance - radius) % period == 0:
                        out[r, c] = marker
                    else:
                        out[r, c] = ray
    return out

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    mark = int(round(params['rule'][1]))
    step = int(round(params['rule'][2]))
    palette_row = int(round(params['rule'][3]))
    fill_row = int(round(params['rule'][4]))
    points = np.argwhere(grid == mark)
    legend = np.argwhere((grid != bg) & (grid != mark))
    if len(points) == 0 or len(legend) == 0 or step <= 0:
        return grid.copy()
    r0 = int(np.min(points[:, 0]))
    r1 = int(np.max(points[:, 0])) + step
    c0 = int(np.min(points[:, 1]))
    c1 = int(np.max(points[:, 1])) + step
    lr0 = int(np.min(legend[:, 0]))
    lr1 = int(np.max(legend[:, 0])) + step
    lc0 = int(np.min(legend[:, 1]))
    lc1 = int(np.max(legend[:, 1])) + step
    key = grid[lr0:lr1, lc0:lc1]
    mask = grid[r0:r1, c0:c1]
    if key.shape[1] != mask.shape[1]:
        return grid.copy()
    if palette_row < -key.shape[0] or palette_row >= key.shape[0]:
        return grid.copy()
    if fill_row < -key.shape[0] or fill_row >= key.shape[0]:
        return grid.copy()
    palette = key[palette_row, :]
    fill = key[fill_row, :]
    return np.where(mask == mark, palette, fill)

def run(params, grid, demos):
    colors = [int(round(v)) for v in params['colors']]
