    cells = int(round(params['geometry'][1]))
    unit = int(round(params['geometry'][2]))
    out = grid.copy()
    if side < 1 or cells < 1 or unit != 1:
        return out
    h, w = grid.shape
    for k in range(len(params['directions'])):
        color = colors[k + unit]
        paint = colors[k + unit + len(params['directions'])]
        direction = int(round(params['directions'][k]))
        for r in range(h - side + unit):
            for c in range(w - side + unit):
                block = grid[r:r + side, c:c + side]
                if np.count_nonzero(block == color) != cells:
                    continue
                missing = np.argwhere(block != color)
                if len(missing) != unit:
                    continue
                mr, mc = missing[0]
                if block[mr, mc] != colors[0]:
                    continue
                dr = (side * int(mr) - unit) * direction
                dc = (side * int(mc) - unit) * direction
                for pos in np.argwhere(block == color):
                    rr = r + int(pos[0]) + dr
                    cc = c + int(pos[1]) + dc
                    if 0 <= rr < h and 0 <= cc < w:
                        if grid[rr, cc] == colors[0]:
                            out[rr, cc] = paint
    return out

