    if step <= 0 or size != step + step + step:
        return grid.copy()
    for value in params['rotations']:
        turns = int(round(value))
        g = np.rot90(grid, turns)
        height, width = g.shape
        if width <= size or height < size:
            continue
        starts = []
        for row in range(height - size + step):
            if np.all(g[row, :size] == black) and np.all(g[row + size - step, :size] == black) and np.all(g[row + step, size - step:] == black):
                starts.append(row)
        if starts:
            out = g.copy()
            out[g == black] = background
            for row in starts:
                out[row:row + size, :size] = background
            for row in starts:
                out[row:row + size, width - size:] = g[row:row + size, :size]
            return np.rot90(out, -turns)
    return grid.copy()

def run(params, grid, demos):
    bg = int(round(params['settings'][0]))
    zero = int(round(params['settings'][1]))
    step = int(round(params['settings'][2]))
    factor = int(round(params['settings'][3]))
    out = grid.copy()
    h, w = grid.shape
    if zero < 0 or step <= zero or step >= min(h, w) or factor <= step:
        return out
    colors = np.unique(grid[grid != bg])
    if len(colors) != step:
        return out
    color = int(colors[zero])
    border = []
    for c in range(zero, w, step):
        border.append((zero, c))
    for r in range(step, h, step):
        border.append((r, w - step))
    for c in range(w - factor * step, zero - step, -step):
        border.append((h - step, c))
    for r in range(h - factor * step, zero, -step):
        border.append((r, zero))
    marked = [grid[r, c] == color for r, c in border]
    length = sum(marked)
    if length <= zero:
        return out
    starts = [i for i in range(len(border)) if marked[i] and not marked[(i - step) % len(border)]]
    if len(starts) != step:
        return out
    start = starts[zero]
    period = factor * length
    for i in range(len(border)):
        r, c = border[i]
        if (i - start) % period < length:
            out[r, c] = color
    return out

def run(params, grid, demos):
    bg = int(round(params['rule'][0]))
    z = int(round(params['rule'][1]))
    step = int(round(params['rule'][2]))
    factor = int(round(params['rule'][3]))
    back = int(round(params['rule'][4]))
    out = grid.copy()
    h, w = grid.shape
    if step == 0 or back == 0:
        return out
    coords = []
    for c in range(z, w, step):
        coords.append((z, c))
    for r in range(step, h, step):
        coords.append((r, w - step))
    for c in range(w - factor, back, back):
        coords.append((h - step, c))
    for r in range(h - factor, z, back):
        coords.append((r, z))
    if len(coords) == 0:
        return out
    for r, c in coords:
        if r < 0 or r >= h or c < 0 or c >= w:
            return out
    marks = [grid[r, c] != bg for r, c in coords]
    n = sum(marks)
    period = factor * n
    if n == 0 or period <= 0:
        return out
    start = None
    for i in range(len(coords)):
        if marks[i] and not marks[(i + back) % len(coords)]:
            start = i
            break
    if start is None:
        return out
    r, c = coords[start]
    color = int(grid[r, c])
    for i in range(len(coords)):
        if (i - start) % period < n:
            r, c = coords[i]
            out[r, c] = color
    return out

def run(params, grid, demos):
    factor = int(round(params['geometry'][0]))
    axis = int(round(params['geometry'][1]))
    first_period = int(round(params['geometry'][2]))
    if factor < 1 or first_period < 1 or axis not in (0, 1):
        return grid.copy()
    work = grid.T if axis == 0 else grid
    height, width = work.shape
    if width * factor > int(round(params['geometry'][3])):
        return grid.copy()
    period = width
    for candidate in range(first_period, width + 1):
        if np.all(work[:, candidate:] == work[:, :width - candidate]):
            period = candidate
            break
    result = np.zeros((height, width * factor), dtype=int)
    for column in range(width * factor):
        result[:, column] = work[:, column % period]
    return result.T if axis == 0 else result

def relations(grid, background, zero):
    colors = [int(c) for c in np.unique(grid) if int(c) != background]
    edges = {c: set() for c in colors}
    for c in colors:
        points = np.argwhere(grid == c).tolist()
        if len(points) <= 1:
            continue
        a = points[zero]
        b = points[-1]
        dr = b[zero] - a[zero]
        dc = b[1] - a[1]
        for r in range(grid.shape[zero]):
            for s in range(grid.shape[1]):
                if (r - a[zero]) * dc == (s - a[1]) * dr:
                    other = int(grid[r, s])
                    if other != background and other != c:
                        edges[c].add(other)
    return colors, edges
def run(params, grid, demos):
    background = int(round(params['settings'][0]))
    zero = int(round(params['settings'][1]))
    one = int(round(params['settings'][2]))
    colors, edges = relations(grid, background, zero)
    prior = {}
    for inp, out in demos:
        sequence = out.flatten().tolist()
        for i in range(len(sequence)):
            for j in range(i + one, len(sequence)):
                pair = (int(sequence[i]), int(sequence[j]))
                prior[pair] = prior.get(pair, zero) + one
    result = []
    remaining = set(colors)
    while remaining:
        available = [c for c in remaining if not any(c in edges[d] for d in remaining)]
        if not available:
            available = list(remaining)
        chosen = min(available, key=lambda c: (sum(prior.get((d, c), zero) - prior.get((c, d), zero) for d in available if d != c), c))
        result.append(chosen)
        remaining.remove(chosen)
    return np.array([result], dtype=int)

def run(params, grid, demos):
    background = int(round(params['background'][0]))
    directions = params['directions']
    h, w = grid.shape
    rr = np.arange(h).reshape(h, 1)
    cc = np.arange(w).reshape(1, w)
    colors = [int(c) for c in np.unique(grid) if int(c) != background]
    masks = []
    visibility = []
    for color in colors:
        positions = np.argwhere(grid == color)
        best_count = -1
        best_mask = grid == color
        for direction in directions:
            a = int(round(direction[0]))
            b = int(round(direction[1]))
            coordinates = a * positions[:, 0] + b * positions[:, 1]
            for intercept in np.unique(coordinates):
                count = int(np.count_nonzero(coordinates == intercept))
                if count > best_count:
                    best_count = count
                    best_mask = a * rr + b * cc == intercept
        masks.append(best_mask)
        visibility.append(float(np.count_nonzero(best_mask & (grid == color))) / max(1, int(np.count_nonzero(best_mask))))
    edges = []
    for i in range(len(colors)):
        for j in range(len(colors)):
            if i != j:
                crossing = masks[i] & masks[j]
                if np.any(crossing & (grid == colors[j])):
                    edges.append((i, j))
    remaining = list(range(len(colors)))
    order = []
    while remaining:
        available = []
        for j in remaining:
            blocked = False
            for lower, upper in edges:
                if upper == j and lower in remaining:
                    blocked = True
            if not blocked:
                available.append(j)
        if not available:
            available = remaining.copy()
        chosen = available[0]
        for j in available:
            if visibility[j] < visibility[chosen]:
                chosen = j
        order.append(colors[chosen])
        remaining.remove(chosen)
    return np.array([order], dtype=int)

def run(params, grid, demos):
    source = int(round(params['colors'][0]))
    fill = int(round(params['colors'][1]))
    background = int(round(params['colors'][2]))
    unit = int(round(params['geometry'][0]))
    minimum_length = int(round(params['geometry'][1]))
    out = grid.copy()
    height = len(grid)
    width = len(grid[0])
    for direction in params['directions']:
        dr = int(round(direction[0]))
        dc = int(round(direction[1]))
        if dr == 0 and dc == 0:
            continue
        for r in range(height):
            for c in range(width):
                if grid[r, c] != source:
                    continue
                previous_r = r - dr
                previous_c = c - dc
                if 0 <= previous_r < height and 0 <= previous_c < width:
                    if grid[previous_r, previous_c] == source:
                        continue
                segment = []
                for distance in range(max(height, width)):
                    rr = r + distance * dr
                    cc = c + distance * dc
                    if not (0 <= rr < height and 0 <= cc < width):
                        break
                    if grid[rr, cc] != source:
                        break
                    segment.append((rr, cc))
                length = len(segment)
                if length < minimum_length:
                    continue
                for index in range(length):
                    rr, cc = segment[index]
                    radius = min(index, length - unit - index)
                    for offset in range(-radius, radius + unit):
                        target_r = rr - offset * dc
                        target_c = cc + offset * dr
                        if 0 <= target_r < height and 0 <= target_c < width:
                            if grid[target_r, target_c] == background:
                                out[target_r, target_c] = fill
    return out

def run(params, grid, demos):
    source = int(round(params['rule'][0]))
