    result = grid.copy()
    for top, bottom in rows:
        for j in range(len(cols)):
            left, right = cols[j]
            other_left, other_right = cols[(j + partner_shift) % len(cols)]
            tile = grid[top:bottom, left:right]
            other = grid[top:bottom, other_left:other_right]
            if tile.shape == other.shape:
                background = int(tile[0, 0])
                other_background = int(other[0, 0])
                result[top:bottom, left:right] = np.where(other != other_background, other_background, background)
    return result

def spans(flags, unit):
    result = []
    start = None
    for i in range(len(flags)):
        if not flags[i]:
            if start is None:
                start = i
        elif start is not None:
            result.append((start, i))
