    exchange = [int(round(v)) for v in params['exchange']]
    if unit <= 0 or group <= 0 or group != len(exchange):
        return grid.copy()
    if axis == unit:
        work = grid.copy()
    else:
        work = grid.T.copy()
    rows = spans(np.all(work == separator, axis=unit), unit)
    cols = spans(np.all(work == separator, axis=unit-unit), unit)
    result = work.copy()
    for top, bottom in rows:
        for first in range(0, len(cols), group):
            if first + group > len(cols):
                continue
            panels = []
            backgrounds = []
            for k in range(group):
                left, right = cols[first+k]
                panel = work[top:bottom, left:right]
                panels.append(panel)
                backgrounds.append(int(panel[0, 0]))
            for k in range(group):
                source = exchange[k]
                if source < 0 or source >= group:
                    continue
                left, right = cols[first+k]
                if panels[source].shape != panels[k].shape:
                    continue
                mask = panels[source] != backgrounds[source]
                result[top:bottom, left:right] = np.where(mask, backgrounds[source], backgrounds[k])
    if axis == unit:
        return result
    return result.T.copy()

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    inset = int(round(params['rule'][1]))
    minimum = int(round(params['rule'][2]))
    if inset <= 0 or minimum <= inset + inset:
        return grid.copy()
    height, width = grid.shape
    best_area = 0
    result = grid.copy()
    for top in range(height):
        for left in range(width):
            color = int(grid[top, left])
            if color == background:
                continue
            for bottom in range(top + minimum, height + inset):
                if bottom > height:
                    continue
                if not np.all(grid[top:bottom, left] == color):
                    continue
                for right in range(left + minimum, width + inset):
                    if right > width:
                        continue
                    area = (bottom - top - inset - inset) * (right - left - inset - inset)
                    if area <= best_area:
                        continue
                    if not np.all(grid[top, left:right] == color):
                        continue
                    if not np.all(grid[bottom - inset, left:right] == color):
                        continue
                    if not np.all(grid[top:bottom, right - inset] == color):
                        continue
                    best_area = area
                    result = grid[top + inset:bottom - inset, left + inset:right - inset].copy()
    return result

