    anchor = None
    markers = [tuple(p) for p in np.argwhere(grid == marker).tolist()]
    for position in np.argwhere(grid != background).tolist():
        start = tuple(position)
        if start in visited:
            continue
        pending = [start]
        visited.add(start)
        component = []
        component_anchor = None
        while pending:
            row, col = pending.pop()
            component.append((row, col))
            if grid[row, col] == marker:
                component_anchor = (row, col)
            for dr, dc in directions:
                nr, nc = row + dr, col + dc
                if 0 <= nr < height and 0 <= nc < width:
                    neighbor = (nr, nc)
                    if neighbor not in visited and grid[nr, nc] != background:
                        visited.add(neighbor)
                        pending.append(neighbor)
        if component_anchor is not None and len(component) > len(source):
            source = component
            anchor = component_anchor
    if anchor is None:
        return result
    source_positions = set(source)
    for target_row, target_col in markers:
        if (target_row, target_col) in source_positions:
            continue
        result[target_row, target_col] = background
        for row, col in source:
            if grid[row, col] == marker:
                continue
            nr = target_row + row - anchor[0]
            nc = target_col + col - anchor[1]
            if 0 <= nr < height and 0 <= nc < width:
                result[nr, nc] = grid[row, col]
    return result

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
