        return out
    anchors = np.argwhere(grid == marker)
    pixels = np.argwhere(np.logical_and(grid != background, grid != marker))
    if len(anchors) < 2 or len(pixels) == 0:
        return out
    scores = []
    for anchor in anchors:
        distances = np.maximum(np.abs(pixels[:, 0] - anchor[0]), np.abs(pixels[:, 1] - anchor[1]))
        scores.append(int(np.count_nonzero(distances <= radius)))
    source_index = int(np.argmax(np.array(scores)))
    if scores[source_index] == 0:
        return out
    source = anchors[source_index]
    for index in range(len(anchors)):
        if index != source_index:
            target = anchors[index]
            out[int(target[0]), int(target[1])] = background
            for pixel in pixels:
                row = int(pixel[0] + target[0] - source[0])
                col = int(pixel[1] + target[1] - source[1])
                if 0 <= row < grid.shape[0] and 0 <= col < grid.shape[1]:
                    out[row, col] = grid[int(pixel[0]), int(pixel[1])]
    return out

