    rotation = int(round(params['rule'][4]))
    unit = int(round(params['rule'][5]))
    h, w = grid.shape
    if depth <= 0 or depth > h or unit <= 0 or unit > w:
        return grid.copy()
    if base_offset < -h or base_offset >= h or slot_offset < -h or slot_offset >= h:
        return grid.copy()
    base_row = base_offset % h
    slot_row = slot_offset % h
    ground = int(grid[base_row, 0])
    objects = []
    for color in np.unique(grid[:slot_row]):
        color = int(color)
        if color == bg or color == ground:
            continue
        points = np.argwhere(grid[:slot_row] == color)
        lo = np.min(points, axis=0)
        hi = np.max(points, axis=0)
        patch = grid[int(lo[0]):int(hi[0]) + unit, int(lo[1]):int(hi[1]) + unit].copy()
        patch = np.where(patch == color, color, bg)
        if patch.shape[0] != depth:
            patch = np.rot90(patch, rotation)
        objects.append(patch)
    gaps = []
    start = None
    for col in range(w):
        if grid[slot_row, col] == bg:
            if start is None:
                start = col
        elif start is not None:
            gaps.append((start, col))
            start = None
    if start is not None:
        gaps.append((start, w))
    out = grid.copy()
    out[np.logical_and(grid != bg, grid != ground)] = bg
    for left, right in gaps:
        chosen = None
        for index in range(len(objects)):
            patch = objects[index]
            if patch.shape[0] == depth and patch.shape[1] == right - left:
                chosen = index
                break
        if chosen is None:
            return grid.copy()
        patch = objects.pop(chosen)
        top = slot_row - depth + unit
        if top < 0:
            return grid.copy()
        out[top:slot_row + unit, left:right] = patch
    if len(objects) != 0:
        return grid.copy()
    return out

def arrange(objects, slots, level, step, turn, used, index):
    if index == len(slots):
        return []
    left, right = slots[index]
    span = right - left
    for item in range(len(objects)):
        if item in used:
            continue
        piece = objects[item]
        for fitted in (piece, np.rot90(piece, turn)):
            if fitted.shape[1] != span:
                continue
            top = level + step - fitted.shape[0]
            if top < 0:
                continue
            remaining = arrange(objects, slots, level, step, turn, used | {item}, index + step)
            if remaining is not None:
                return [(top, left, right, fitted)] + remaining
    return None
