    for color in np.unique(grid):
        color = int(color)
        if color == bg or color == base:
            continue
        points = np.argwhere(grid == color)
        top = int(np.min(points[:, 0]))
        bottom = int(np.max(points[:, 0])) + step
        left = int(np.min(points[:, 1]))
        right = int(np.max(points[:, 1])) + step
        objects.append(grid[top:bottom, left:right].copy())
        out[grid == color] = bg
    slots = []
    col = 0
    while col < width:
        if grid[level, col] == bg:
            start = col
            while col < width and grid[level, col] == bg:
                col += step
            slots.append((start, col))
        else:
            col += step
    if len(objects) != len(slots):
        return grid.copy()
    placements = arrange(objects, slots, level, step, turn, set(), 0)
    if placements is None:
        return grid.copy()
    for top, left, right, fitted in placements:
        out[top:level + step, left:right] = fitted
    return out

