            continue
        color = original[r, c]
        for direction in params['directions']:
            dr = int(round(direction[0]))
            dc = int(round(direction[1]))
            if dr == 0 and dc == 0:
                continue
            endpoint_r = r
            endpoint_c = c
            if dr < 0:
                endpoint_r = 0
            elif dr > 0:
                endpoint_r = h - 1
            if dc < 0:
                endpoint_c = 0
            elif dc > 0:
                endpoint_c = w - 1
            if original[endpoint_r, endpoint_c] != color:
                continue
            rr = r
            cc = c
            while 0 < rr < h - 1 and 0 < cc < w - 1:
                result[rr, cc] = color
