    for r, c in reds:
        touches = False
        for direction in params['neighbors']:
            dr = int(round(direction[0]))
            dc = int(round(direction[1]))
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                if grid[rr, cc] == ink:
                    touches = True
        if touches:
            anchors.append([r, c])
    if not anchors or not blues:
        return out
    for r, c in reds:
        if r >= step and grid[r - step, c] == mark:
            continue
        if c >= step and grid[r, c - step] == mark:
            continue
        size = step
        while c + size < w and grid[r, c + size] == mark:
            size += step
        if r + size > h or c + size > w:
            continue
        if not np.all(grid[r:r + size, c:c + size] == mark):
            continue
        if r + size < h and grid[r + size, c] == mark:
            continue
        for ar, ac in anchors:
            origin_r = r - ar * size
            origin_c = c - ac * size
            valid = True
            for tr, tc in anchors:
                rr = origin_r + tr * size
                cc = origin_c + tc * size
                if rr < 0 or cc < 0 or rr + size > h or cc + size > w:
                    valid = False
                    break
                if not np.all(grid[rr:rr + size, cc:cc + size] == mark):
                    valid = False
                    break
            if valid:
                for br, bc in blues:
                    rr = origin_r + br * size
                    cc = origin_c + bc * size
                    for dy in range(0, size, step):
                        for dx in range(0, size, step):
                            y, x = rr + dy, cc + dx
                            if 0 <= y < h and 0 <= x < w:
                                if grid[y, x] == bg or grid[y, x] == ink:
                                    out[y, x] = ink
    return out
